export type NodeRunStatus = "RUNNING" | "SUCCEEDED" | "FAILED" | "SKIPPED";

export interface GraphNodeSpec {
  name: string;
  label_en: string;
  label_vi: string;
  kind: NodeKind;
  purpose_en: string;
  purpose_vi: string;
  inputs: string[];
  outputs: string[];
  db_tables: string[];
  source: string;
}

export interface GraphEdgeSpec {
  from: string;
  to: string;
  condition?: string;
}

export interface GraphSpec {
