:root {
  --graph-llm: #2563eb;
  --graph-llm-soft: #eaf1ff;
  --graph-deterministic: #2f6f4e;
  --graph-deterministic-soft: #e8f4ed;
  --graph-gate: #a56824;
  --graph-gate-soft: #fdf1de;
  --graph-idle: #9aa6bd;
  --graph-idle-soft: #f2f5fa;
  --graph-failed: #b94d4d;
}

:root[data-theme="dark"] {
  --graph-llm: #60a5fa;
  --graph-llm-soft: #1d3158;
  --graph-deterministic: #5fbe87;
  --graph-deterministic-soft: #16341f;
  --graph-gate: #d6a54a;
  --graph-gate-soft: #3a2c12;
  --graph-idle: #6d7c99;
  --graph-idle-soft: #1a2947;
  --graph-failed: #e0796a;
}

/* --- Khối gấp/mở nhúng trong từng bước wizard --------------------------- */

.graph-stage-panel {
  margin-top: 18px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  overflow: hidden;
}

.graph-stage-toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  background: var(--surface-muted);
  border: 0;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  color: var(--ink);
  text-align: left;
}

.graph-stage-toggle:hover {
  background: var(--accent-soft);
}

.graph-stage-toggle-meta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
}

.graph-stage-live {
  color: var(--accent);
  font-weight: 600;
}

.graph-stage-live::before {
  content: "\25CF";
  margin-right: 4px;
  animation: graph-pulse 1.4s ease-in-out infinite;
}

.graph-stage-failed {
  color: var(--graph-failed);
  font-weight: 600;
}

.graph-stage-chevron {
  color: var(--muted);
}

.graph-stage-body {
  padding: 18px 16px;
  display: grid;
  gap: 22px;
}

.graph-stage-graph {
  display: grid;
  gap: 14px;
}

@keyframes graph-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

/* --- Chuỗi node ---------------------------------------------------------- */

.graph-flow-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.graph-flow-head h3 {
  margin: 4px 0 2px;
  font-size: 16px;
}

.graph-flow-head p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  max-width: 62ch;
}

.graph-flow-stats {
  display: flex;
  gap: 20px;
}

.graph-flow-stats div {
  display: grid;
  gap: 2px;
  text-align: right;
}

.graph-flow-stats strong {
  font-size: 16px;
  font-variant-numeric: tabular-nums;
}

.graph-flow-stats span {
  font-size: 11px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.graph-flow-failed strong {
  color: var(--graph-failed);
}

/* Sơ đồ có thể rộng hơn khung; cuộn trong chính nó để thân trang không bao
   giờ cuộn ngang. */
.graph-flow-track {
  display: flex;
  align-items: stretch;
  overflow-x: auto;
  padding-bottom: 8px;
}

.graph-flow-item {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
}

.graph-flow-arrow {
  position: relative;
  flex: 0 0 auto;
  width: 46px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.graph-flow-arrow-line {
  width: 100%;
  height: 2px;
  background: var(--border);
  position: relative;
}

.graph-flow-arrow-line::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  border-left: 6px solid var(--border);
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
}

.graph-flow-arrow-label {
  position: absolute;
  top: -16px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  color: var(--muted);
  white-space: nowrap;
  background: var(--surface);
  padding: 0 4px;
}

/* --- Thẻ node ------------------------------------------------------------ */

.graph-node-card {
  width: 208px;
  min-height: 152px;
  display: grid;
  align-content: start;
  gap: 6px;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid var(--border);
  border-left: 4px solid var(--graph-idle);
  background: var(--surface);
  cursor: pointer;
  text-align: left;
  color: var(--ink);
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.graph-node-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.graph-node-card.selected {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.graph-node-card.kind-llm { border-left-color: var(--graph-llm); }
.graph-node-card.kind-deterministic { border-left-color: var(--graph-deterministic); }
.graph-node-card.kind-gate { border-left-color: var(--graph-gate); }

/* Node chưa chạy phải trông "chưa tới lượt", không phải "hỏng". */
.graph-node-card.state-idle {
  background: var(--graph-idle-soft);
  opacity: 0.72;
}

.graph-node-card.state-failed {
  border-color: var(--graph-failed);
}

.graph-node-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.graph-node-kind {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 999px;
}

.graph-node-kind.kind-llm {
  color: var(--graph-llm);
  background: var(--graph-llm-soft);
}

.graph-node-kind.kind-deterministic {
  color: var(--graph-deterministic);
  background: var(--graph-deterministic-soft);
}

.graph-node-kind.kind-gate {
  color: var(--graph-gate);
  background: var(--graph-gate-soft);
}

.graph-node-status {
  font-size: 13px;
  font-weight: 700;
}

.graph-node-status.state-succeeded { color: var(--graph-deterministic); }
.graph-node-status.state-failed { color: var(--graph-failed); }
.graph-node-status.state-running {
  color: var(--accent);
  animation: graph-pulse 1.4s ease-in-out infinite;
}
.graph-node-status.state-skipped { color: var(--muted); }

.graph-node-name {
  font-size: 13.5px;
  line-height: 1.3;
}

.graph-node-id {
  font-size: 10.5px;
  color: var(--muted);
  word-break: break-all;
}

.graph-node-purpose {
  margin: 2px 0 0;
  font-size: 11.5px;
  line-height: 1.45;
  color: var(--ink-soft);
}

.graph-node-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding-top: 6px;
  font-size: 11px;
  color: var(--muted);
  flex-wrap: wrap;
}

.graph-node-duration {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--ink-soft);
}

.graph-node-duration.muted {
  font-weight: 400;
  color: var(--muted);
}

.graph-node-model {
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--surface-muted);
}

/* --- Thanh thời lượng ---------------------------------------------------- */

.graph-timeline {
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px 14px;
  background: var(--surface-muted);
}

.graph-timeline-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}

.graph-timeline-total {
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.graph-timeline-rows {
  list-style: none;
  margin: 0;
  padding: 0;
