}

.graph-timeline-row:disabled {
  cursor: default;
}

.graph-timeline-row:hover:not(:disabled) .graph-timeline-label code {
  color: var(--accent);
}

.graph-timeline-label {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.graph-timeline-label code {
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.graph-timeline-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: 0 0 auto;
}

.graph-timeline-dot.kind-llm { background: var(--graph-llm); }
.graph-timeline-dot.kind-deterministic { background: var(--graph-deterministic); }
.graph-timeline-dot.kind-gate { background: var(--graph-gate); }

.graph-timeline-bar-track {
  height: 9px;
  border-radius: 999px;
