.graph-drawer-head h3 {
  margin: 8px 0 3px;
  font-size: 17px;
}

.graph-drawer-head code {
  font-size: 11.5px;
  color: var(--muted);
}

.graph-drawer-close {
  background: none;
  border: 0;
  font-size: 17px;
  cursor: pointer;
  color: var(--muted);
  padding: 4px;
}

.graph-drawer-close:hover {
  color: var(--ink);
}

.graph-drawer-body {
  padding: 18px 20px 28px;
  overflow-y: auto;
  display: grid;
  gap: 20px;
  align-content: start;
}

.graph-drawer-body p {
  margin: 5px 0 0;
  font-size: 13px;
  line-height: 1.55;
  color: var(--ink-soft);
}

.graph-drawer-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px;
  padding: 14px;
  border-radius: 12px;
  background: var(--surface-muted);
}

.graph-drawer-metrics div {
  display: grid;
  gap: 3px;
}

.graph-drawer-metrics span {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.graph-drawer-metrics strong {
  font-size: 14px;
}

.graph-drawer-metrics strong.state-succeeded { color: var(--graph-deterministic); }
.graph-drawer-metrics strong.state-failed { color: var(--graph-failed); }
.graph-drawer-metrics strong.state-running { color: var(--accent); }

.graph-drawer-empty {
  padding: 14px;
  border-radius: 12px;
  background: var(--graph-idle-soft);
  color: var(--muted);
  font-size: 13px;
}

.graph-drawer-error pre {
  margin: 6px 0 0;
  padding: 12px;
  border-radius: 10px;
  background: var(--surface-muted);
  border-left: 3px solid var(--graph-failed);
  color: var(--graph-failed);
  font-size: 11.5px;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-x: auto;
}

.graph-drawer-error-text {
  font-size: 12.5px;
  color: var(--graph-failed);
}

.graph-drawer-loading {
  font-size: 12.5px;
  color: var(--muted);
}

.graph-drawer-contract {
  display: grid;
  gap: 14px;
}

.graph-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
}

.graph-chip-row code {
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--surface-muted);
  border: 1px solid var(--border);
}

.graph-drawer-privacy {
  font-size: 11.5px !important;
  color: var(--muted) !important;
  font-style: italic;
}

.graph-summary-panes {
  display: grid;
  gap: 14px;
  margin-top: 10px;
}

.graph-summary-panes h4 {
  margin: 0 0 6px;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.graph-summary-object {
  margin: 0;
  display: grid;
  gap: 3px;
  font-size: 11.5px;
}

.graph-summary-object.depth-1,
.graph-summary-object.depth-2,
.graph-summary-object.depth-3 {
  padding-left: 10px;
  border-left: 1px solid var(--border);
}

.graph-summary-entry {
  display: grid;
  grid-template-columns: minmax(90px, 34%) 1fr;
  gap: 8px;
  align-items: start;
}

.graph-summary-entry dt {
  color: var(--muted);
  word-break: break-word;
}

.graph-summary-entry dd {
  margin: 0;
  min-width: 0;
  word-break: break-word;
}

.graph-summary-scalar {
  color: var(--ink-soft);
}

.graph-summary-null {
  color: var(--muted);
}

.graph-summary-list {
  margin: 0;
  padding-left: 16px;
  display: grid;
  gap: 2px;
}

.graph-drawer-source code {
  display: block;
  margin-top: 6px;
  font-size: 11px;
  color: var(--ink-soft);
  word-break: break-all;
}

/* --- Trang Graph Observatory --------------------------------------------- */

.graph-observatory {
  display: grid;
  gap: 22px;
}

.graph-observatory-actions {
  display: flex;
  gap: 10px;
}

.graph-observatory-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 14px;
}

.graph-observatory-metrics article {
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  display: grid;
  gap: 4px;
  align-content: start;
}

.graph-observatory-metrics strong {
  font-size: 26px;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.graph-observatory-metrics small {
  font-size: 11px;
  color: var(--muted);
}

.graph-metric-danger strong {
  color: var(--graph-failed);
}

.graph-observatory-filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.graph-filter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--ink-soft);
  cursor: pointer;
  font-size: 12.5px;
  font-weight: 600;
}

.graph-filter:hover {
  border-color: var(--accent);
}

.graph-filter.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
}

.graph-filter-count {
  font-size: 10.5px;
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--surface-muted);
  color: var(--ink-soft);
}

.graph-filter.active .graph-filter-count {
  background: rgb(255 255 255 / 24%);
  color: var(--on-accent);
}

.graph-observatory-list {
  display: grid;
  gap: 20px;
}

.graph-observatory-card {
  padding: 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  display: grid;
  gap: 16px;
}

/* --- Báo cáo Steward (đầu ra Graph 3) ------------------------------------ */

.steward-report-panel {
  margin-bottom: 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  overflow: hidden;
}

.steward-report-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px;
  flex-wrap: wrap;
}

.steward-report-head strong {
  display: block;
  margin: 5px 0 3px;
  font-size: 15px;
}

.steward-report-head p {
  margin: 0;
  font-size: 12.5px;
  color: var(--muted);
}

.steward-report-empty {
  padding: 0 18px 16px;
  font-size: 12.5px;
  color: var(--muted);
}

.steward-report-body {
  border-top: 1px solid var(--border);
}

.steward-report-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 18px;
  background: var(--surface-muted);
  font-size: 11.5px;
  color: var(--muted);
  flex-wrap: wrap;
}

.steward-report-content {
  margin: 0;
  padding: 18px;
  max-height: 460px;
  overflow: auto;
  font-size: 12.5px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--ink-soft);
}

@media (max-width: 720px) {
  .graph-drawer {
    width: 100vw;
  }

  .graph-timeline-row {
    grid-template-columns: minmax(96px, 40%) 1fr 60px;
  }

  .graph-flow-stats {
    gap: 14px;
  }
}

tool_input.content:
/* ==========================================================================
   HIỂN THỊ NODE CỦA ĐỒ THỊ AGENT

   Ba màu phân loại node bám theo quy ước đã dùng trong analyze_ete.md: node
   LLM xanh dương, node tất định xanh lá, chốt HITL vàng hổ phách. Giữ nguyên
   bảng màu đó khiến sơ đồ trên giao diện đọc được cùng một cách với sơ đồ
   trong tài liệu, không phải học lại lần nữa.

   Các token dưới đây có biến thể nền tối riêng vì sắc xanh lá và hổ phách gốc
   quá sẫm khi đặt trên nền tối.
   ========================================================================== */

:root {
  --graph-llm: #2563eb;
  --graph-llm-soft: #eaf1ff;
  --graph-deterministic: #2f6f4e;
  --graph-deterministic-soft: #e8f4ed;
  --graph-gate: #a56824;
  --graph-gate-soft: #fdf1de;
  --graph-idle: #9aa6bd;
  --graph-idle-soft: #f2f5fa;
  --graph-failed: #b94d4d;
}

:root[data-theme="dark"] {
  --graph-llm: #60a5fa;
  --graph-llm-soft: #1d3158;
  --graph-deterministic: #5fbe87;
  --graph-deterministic-soft: #16341f;
  --graph-gate: #d6a54a;
  --graph-gate-soft: #3a2c12;
  --graph-idle: #6d7c99;
  --graph-idle-soft: #1a2947;
  --graph-failed: #e0796a;
}

/* --- Khối gấp/mở nhúng trong từng bước wizard --------------------------- */

.graph-stage-panel {
  margin-top: 18px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  overflow: hidden;
}

.graph-stage-toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  background: var(--surface-muted);
  border: 0;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  color: var(--ink);
  text-align: left;
}

.graph-stage-toggle:hover {
  background: var(--accent-soft);
}

.graph-stage-toggle-meta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
}

.graph-stage-live {
  color: var(--accent);
  font-weight: 600;
}

.graph-stage-live::before {
  content: "\25CF";
  margin-right: 4px;
  animation: graph-pulse 1.4s ease-in-out infinite;
}

.graph-stage-failed {
  color: var(--graph-failed);
  font-weight: 600;
}

.graph-stage-chevron {
  color: var(--muted);
}

.graph-stage-body {
  padding: 18px 16px;
  display: grid;
  gap: 22px;
}

.graph-stage-graph {
  display: grid;
  gap: 14px;
}

@keyframes graph-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

/* --- Chuỗi node ---------------------------------------------------------- */

.graph-flow-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.graph-flow-head h3 {
  margin: 4px 0 2px;
  font-size: 16px;
}

.graph-flow-head p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  max-width: 62ch;
}

.graph-flow-stats {
  display: flex;
  gap: 20px;
}

.graph-flow-stats div {
  display: grid;
  gap: 2px;
  text-align: right;
}

.graph-flow-stats strong {
  font-size: 16px;
  font-variant-numeric: tabular-nums;
}

.graph-flow-stats span {
  font-size: 11px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.graph-flow-failed strong {
  color: var(--graph-failed);
}

/* Sơ đồ có thể rộng hơn khung; cuộn trong chính nó để thân trang không bao
   giờ cuộn ngang. */
.graph-flow-track {
  display: flex;
  align-items: stretch;
  overflow-x: auto;
  padding-bottom: 8px;
}

.graph-flow-item {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
}

.graph-flow-arrow {
  position: relative;
  flex: 0 0 auto;
  width: 46px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.graph-flow-arrow-line {
  width: 100%;
  height: 2px;
  background: var(--border);
  position: relative;
}

.graph-flow-arrow-line::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  border-left: 6px solid var(--border);
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
}

.graph-flow-arrow-label {
  position: absolute;
  top: -16px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  color: var(--muted);
  white-space: nowrap;
  background: var(--surface);
  padding: 0 4px;
}

/* --- Thẻ node ------------------------------------------------------------ */

.graph-node-card {
  width: 208px;
  min-height: 152px;
  display: grid;
  align-content: start;
  gap: 6px;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid var(--border);
  border-left: 4px solid var(--graph-idle);
  background: var(--surface);
  cursor: pointer;
  text-align: left;
  color: var(--ink);
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.graph-node-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.graph-node-card.selected {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.graph-node-card.kind-llm { border-left-color: var(--graph-llm); }
.graph-node-card.kind-deterministic { border-left-color: var(--graph-deterministic); }
.graph-node-card.kind-gate { border-left-color: var(--graph-gate); }

/* Node chưa chạy phải trông "chưa tới lượt", không phải "hỏng". */
.graph-node-card.state-idle {
  background: var(--graph-idle-soft);
  opacity: 0.72;
}

.graph-node-card.state-failed {
  border-color: var(--graph-failed);
}

.graph-node-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.graph-node-kind {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 999px;
}

.graph-node-kind.kind-llm {
  color: var(--graph-llm);
  background: var(--graph-llm-soft);
}

.graph-node-kind.kind-deterministic {
  color: var(--graph-deterministic);
  background: var(--graph-deterministic-soft);
}

.graph-node-kind.kind-gate {
  color: var(--graph-gate);
  background: var(--graph-gate-soft);
}

.graph-node-status {
  font-size: 13px;
  font-weight: 700;
}

.graph-node-status.state-succeeded { color: var(--graph-deterministic); }
.graph-node-status.state-failed { color: var(--graph-failed); }
.graph-node-status.state-running {
  color: var(--accent);
  animation: graph-pulse 1.4s ease-in-out infinite;
}
.graph-node-status.state-skipped { color: var(--muted); }

.graph-node-name {
  font-size: 13.5px;
  line-height: 1.3;
}

.graph-node-id {
  font-size: 10.5px;
  color: var(--muted);
  word-break: break-all;
}

.graph-node-purpose {
  margin: 2px 0 0;
  font-size: 11.5px;
  line-height: 1.45;
  color: var(--ink-soft);
}

.graph-node-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding-top: 6px;
  font-size: 11px;
  color: var(--muted);
  flex-wrap: wrap;
}

.graph-node-duration {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--ink-soft);
}

.graph-node-duration.muted {
  font-weight: 400;
  color: var(--muted);
}

.graph-node-model {
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--surface-muted);
}

/* --- Thanh thời lượng ---------------------------------------------------- */

.graph-timeline {
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px 14px;
  background: var(--surface-muted);
}

.graph-timeline-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}

.graph-timeline-total {
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.graph-timeline-rows {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 5px;
}

.graph-timeline-row {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(140px, 210px) 1fr 72px;
  align-items: center;
  gap: 12px;
  background: none;
  border: 0;
  padding: 3px 0;
  cursor: pointer;
  color: inherit;
  text-align: left;
}

.graph-timeline-row:disabled {
  cursor: default;
}

.graph-timeline-row:hover:not(:disabled) .graph-timeline-label code {
  color: var(--accent);
}

.graph-timeline-label {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.graph-timeline-label code {
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.graph-timeline-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: 0 0 auto;
}

.graph-timeline-dot.kind-llm { background: var(--graph-llm); }
.graph-timeline-dot.kind-deterministic { background: var(--graph-deterministic); }
.graph-timeline-dot.kind-gate { background: var(--graph-gate); }

.graph-timeline-bar-track {
  height: 9px;
  border-radius: 999px;
  background: var(--border);
  overflow: hidden;
}

.graph-timeline-bar {
  display: block;
  height: 100%;
  border-radius: 999px;
}

.graph-timeline-bar.kind-llm { background: var(--graph-llm); }
.graph-timeline-bar.kind-deterministic { background: var(--graph-deterministic); }
.graph-timeline-bar.kind-gate { background: var(--graph-gate); }
.graph-timeline-bar.state-failed { background: var(--graph-failed); }

.graph-timeline-value {
  font-size: 11px;
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
}

/* --- Panel chi tiết trượt ra --------------------------------------------- */

.graph-drawer-scrim {
  position: fixed;
  inset: 0;
  background: rgb(10 18 34 / 42%);
  z-index: 60;
}

.graph-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(520px, 100vw);
  background: var(--surface);
  border-left: 1px solid var(--border);
  box-shadow: var(--shadow);
  z-index: 61;
  display: flex;
  flex-direction: column;
}

.graph-drawer-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--border);
}

.graph-drawer-head h3 {
  margin: 8px 0 3px;
  font-size: 17px;
}

.graph-drawer-head code {
  font-size: 11.5px;
  color: var(--muted);
}

.graph-drawer-close {
  background: none;
  border: 0;
  font-size: 17px;
  cursor: pointer;
  color: var(--muted);
  padding: 4px;
}

.graph-drawer-close:hover {
  color: var(--ink);
}

.graph-drawer-body {
  padding: 18px 20px 28px;
  overflow-y: auto;
  display: grid;
  gap: 20px;
  align-content: start;
}

.graph-drawer-body p {
  margin: 5px 0 0;
  font-size: 13px;
  line-height: 1.55;
  color: var(--ink-soft);
}

.graph-drawer-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px;
  padding: 14px;
  border-radius: 12px;
  background: var(--surface-muted);
}

.graph-drawer-metrics div {
  display: grid;
  gap: 3px;
}

.graph-drawer-metrics span {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.graph-drawer-metrics strong {
  font-size: 14px;
}

.graph-drawer-metrics strong.state-succeeded { color: var(--graph-deterministic); }
.graph-drawer-metrics strong.state-failed { color: var(--graph-failed); }
.graph-drawer-metrics strong.state-running { color: var(--accent); }

.graph-drawer-empty {
  padding: 14px;
  border-radius: 12px;
  background: var(--graph-idle-soft);
  color: var(--muted);
  font-size: 13px;
}

.graph-drawer-error pre {
  margin: 6px 0 0;
  padding: 12px;
  border-radius: 10px;
  background: var(--surface-muted);
  border-left: 3px solid var(--graph-failed);
  color: var(--graph-failed);
  font-size: 11.5px;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-x: auto;
}

.graph-drawer-error-text {
  font-size: 12.5px;
  color: var(--graph-failed);
}

.graph-drawer-loading {
  font-size: 12.5px;
  color: var(--muted);
}

.graph-drawer-contract {
  display: grid;
  gap: 14px;
}

.graph-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
}

.graph-chip-row code {
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--surface-muted);
  border: 1px solid var(--border);
}

.graph-drawer-privacy {
  font-size: 11.5px !important;
  color: var(--muted) !important;
  font-style: italic;
}

.graph-summary-panes {
  display: grid;
  gap: 14px;
  margin-top: 10px;
