  background: var(--surface);
  display: grid;
  gap: 4px;
  align-content: start;
}

.graph-observatory-metrics strong {
  font-size: 26px;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.graph-observatory-metrics small {
  font-size: 11px;
  color: var(--muted);
}

.graph-metric-danger strong {
  color: var(--graph-failed);
}

.graph-observatory-filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.graph-filter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--ink-soft);
  cursor: pointer;
  font-size: 12.5px;
  font-weight: 600;
}

.graph-filter:hover {
  border-color: var(--accent);
}

.graph-filter.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
}

.graph-filter-count {
  font-size: 10.5px;
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--surface-muted);
  color: var(--ink-soft);
}

.graph-filter.active .graph-filter-count {
  background: rgb(255 255 255 / 24%);
  color: var(--on-accent);
}

.graph-observatory-list {
  display: grid;
  gap: 20px;
}

.graph-observatory-card {
  padding: 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  display: grid;
  gap: 16px;
}

/* --- Báo cáo Steward (đầu ra Graph 3) ------------------------------------ */

.steward-report-panel {
  margin-bottom: 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  overflow: hidden;
