        async def node(state):
            return {"error": "dbt project validation failed"}

        await node({})

        row = _node_runs(db_session, "validate_dbt_project")[0]
        assert row.status == "FAILED"
        assert "validation failed" in row.error_message

    @pytest.mark.asyncio
    async def test_nodes_of_one_run_share_a_graph_run_id_and_order(self, db_session):
        start_graph_run(dataset_id="ds-5")

        @instrument("G1B", "rule_candidate_builder", "DETERMINISTIC")
        async def first(state):
            return {}

        @instrument("G1B", "rule_proposer", "LLM")
        async def second(state):
            return {}

        await first({})
        await second({})

        rows = _node_runs(db_session, "rule_candidate_builder") + _node_runs(db_session, "rule_proposer")
        assert len({row.graph_run_id for row in rows}) == 1
        assert sorted(row.sequence for row in rows) == [1, 2]


def _node_runs(db_session, node_name: str):
    from src.models.database import GraphNodeRunModel

    return db_session.query(GraphNodeRunModel).filter_by(node_name=node_name).all()

