            {failed > 0 ? t("analytics.reviewSource") : t("analytics.noRuleFailed")}
          </div>
        </div>
      </div>

      <div className="analytics-charts">
        <div className="analytics-card">
          <h3>{t("analytics.rulePerformance")}</h3>
          <div className="analytics-chart-frame">
