            ) : (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={barData}>
                  <XAxis dataKey="name" stroke="currentColor" className="chart-axis" />
                  <YAxis allowDecimals={false} stroke="currentColor" className="chart-axis" />
                  <Tooltip />
                  <Bar dataKey="count">
