.explorer-dialog-scrim {
  position: fixed;
  inset: 0;
  background: rgb(10 18 34 / 46%);
  z-index: 70;
}

.explorer-dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(1100px, calc(100vw - 40px));
  max-height: calc(100vh - 64px);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  z-index: 71;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.explorer-dialog-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 22px;
  border-bottom: 1px solid var(--border);
}

.explorer-dialog-head h3 {
  margin: 6px 0 4px;
  font-size: 18px;
}

.explorer-dialog-head p {
  margin: 0;
  font-size: 12.5px;
  color: var(--muted);
}

.explorer-dialog-close {
  background: none;
  border: 0;
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
  color: var(--muted);
  padding: 6px;
  border-radius: 8px;
}

.explorer-dialog-close:hover {
  color: var(--ink);
  background: var(--surface-muted);
}

.explorer-dialog-body {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.explorer-dialog-state {
  padding: 40px 22px;
  text-align: center;
  color: var(--muted);
  font-size: 13px;
}

.explorer-dialog-state.error {
